import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-09-03","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-09-03","date":"2025-09-03T00:00:00.000Z","updated":"2025-09-08T00:00:00.000Z","tags":["Ceph","RGW","存储","分布式存储","Ceph RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-03.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-03.md","lastUpdated":1780460162000}'),l={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-03.md"};function r(c,e,n,d,s,_){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>本次会议主要讨论了Ceph RGW的优化和改进，以下是会议的关键细节：</p><h3 id="_1-create-bucket-逻辑优化" tabindex="-1">1. <code>create bucket</code> 逻辑优化 <a class="header-anchor" href="#_1-create-bucket-逻辑优化" aria-label="Permalink to &quot;1. `create bucket` 逻辑优化&quot;">​</a></h3><ul><li><strong>问题背景</strong>: 客户频繁调用<code>create bucket</code>用于检查桶是否存在，导致集群性能下降。</li><li><strong>讨论内容</strong>: <ul><li>现有逻辑在确认桶存在后仍会创建并删除冗余对象，影响性能。</li><li>S3场景：若桶存在且无元数据变更，应直接返回<code>BucketExists</code>错误，无需操作后端存储。</li><li>Swift场景：允许元数据更新，但不应重复创建<code>rados objects</code>。</li></ul></li><li><strong>后续行动</strong>: Kernel将提交PR优化逻辑，确保仅在必要时操作后端。</li></ul><h3 id="_2-用户迁移至账户时的权限问题" tabindex="-1">2. 用户迁移至账户时的权限问题 <a class="header-anchor" href="#_2-用户迁移至账户时的权限问题" aria-label="Permalink to &quot;2. 用户迁移至账户时的权限问题&quot;">​</a></h3><ul><li><strong>问题描述</strong>: 用户迁移到账户后，桶的<code>ACL</code>中<code>owner</code>字段更新为账户ID，但<code>policy</code>字段仍保留旧用户UID，导致权限冲突。</li><li><strong>结论</strong>: 此为代码疏漏，需同时更新<code>ACL</code>的<code>owner</code>和<code>policy</code>字段。</li><li><strong>后续行动</strong>: Kernel将提交PR修复此问题。</li></ul><h3 id="_3-ceph-developer-summit-cds-安排" tabindex="-1">3. Ceph Developer Summit (CDS) 安排 <a class="header-anchor" href="#_3-ceph-developer-summit-cds-安排" aria-label="Permalink to &quot;3. Ceph Developer Summit (CDS) 安排&quot;">​</a></h3><ul><li>CDS已启动，RGW相关会议计划在下周三复用常规会议时间。</li><li>议题征集：稳定性改进、Reef版本的RGW新功能规划。</li></ul><h3 id="_4-稳定性改进讨论" tabindex="-1">4. 稳定性改进讨论 <a class="header-anchor" href="#_4-稳定性改进讨论" aria-label="Permalink to &quot;4. 稳定性改进讨论&quot;">​</a></h3><ul><li>近期在重构会议中讨论了稳定性优化，但尚无具体方案。</li><li>计划在后续Ceph Steering Committee (CSC)会议中进一步推进。</li></ul><h3 id="_5-行动计划" tabindex="-1">5. 行动计划 <a class="header-anchor" href="#_5-行动计划" aria-label="Permalink to &quot;5. 行动计划&quot;">​</a></h3><ul><li>提交<code>create bucket</code>逻辑优化PR：Kernel，1-2天内。</li><li>修复账户迁移的ACL同步问题PR：Kernel，近期。</li><li>更新会议结论至Tracker Issue：Kernel，会后。</li><li>完善 CDS RGW 议题（Roadmap/新功能）：全体，下周会议前。</li></ul><p>本次会议重点关注了Ceph RGW的性能优化和稳定性改进，并对一些重要问题进行了讨论和决策，为后续的开发工作提供了明确的方向。</p>',12)])])}const u=t(l,[["render",r]]);export{h as __pageData,u as default};
